"""Analysis buttons after "Muéstrame <objeto>" (app/analysis_actions.py)."""

from __future__ import annotations

import json
from typing import Any

from app import analysis_actions
from app.gateways.direct import _GalaxyEventFilter

# Texts generated by the Galaxy API for task "resolve" (agent_tools.py) and its
# fallback (orchestrator.py).
RESOLVE = (
    "Aquí tienes M51. Ajusta el encuadre, el zoom y la banda en el visor como prefieras. "
    "Cuando estés listo, dime qué quieres analizar: morfología completa, segmentación e "
    "isofotas, fotometría básica, o perfil de brillo."
)
FALLBACK = (
    "Aquí tienes RA 202.4696° Dec 47.1952°. Ajusta el encuadre, el zoom y la banda en el "
    "visor como prefieras. Cuando estés listo, dime qué quieres analizar."
)


def _sse(payload: dict[str, Any]) -> bytes:
    return f"event: {payload['type']}\ndata: {json.dumps(payload)}\n\n".encode()


def _events(stream: bytes) -> list[dict[str, Any]]:
    filt = _GalaxyEventFilter("req-1")
    out = b"".join(filt.feed(stream) + filt.finish()).decode()
    return [
        json.loads(line[5:].strip())
        for block in out.split("\n\n")
        for line in block.splitlines()
        if line.startswith("data:")
    ]


def test_resolve_answer_gets_buttons_and_a_shorter_text() -> None:
    stream = _sse({"type": "summary", "summary": RESOLVE}) + _sse(
        {
            "type": "end",
            "request_id": "req-1",
            "status": "success",
            "summary": RESOLVE,
            "object_name": "M51",
            "coordinates": {"ra_deg": 202.47},
        }
    )
    summary, end = _events(stream)
    expected = (
        "Aquí tienes M51. Ajusta el encuadre, el zoom y la banda en el visor como prefieras. "
        + analysis_actions.SHORT_PROMPT
    )
    assert summary["summary"] == expected and "suggested_actions" not in summary
    assert end["summary"] == expected
    assert end["coordinates"] == {"ra_deg": 202.47} and end["object_name"] == "M51"
    assert [a["label"] for a in end["suggested_actions"]] == [
        "Morfología completa",
        "Segmentación e isofotas",
        "Fotometría básica",
        "Perfil de brillo",
    ]
    assert end["suggested_actions"][0]["message"] == "Analiza la morfología completa de M51"
    assert all("M51" in a["message"] for a in end["suggested_actions"])


def test_fallback_text_without_object_name_uses_the_label() -> None:
    (end,) = _events(_sse({"type": "end", "status": "success", "summary": FALLBACK}))
    assert end["summary"].endswith(analysis_actions.SHORT_PROMPT)
    assert end["suggested_actions"][3]["message"] == (
        "Calcula el perfil de brillo de RA 202.4696° Dec 47.1952°"
    )


def test_analysis_results_are_untouched() -> None:
    stream = _sse({"type": "summary", "summary": "M51 es una espiral de gran diseño…"}) + _sse(
        {"type": "end", "status": "success", "summary": "M51 es una espiral de gran diseño…"}
    )
    filt = _GalaxyEventFilter("req-1")
    assert b"".join(filt.feed(stream) + filt.finish()) == stream


def test_unknown_name_falls_back_to_a_generic_label() -> None:
    actions = analysis_actions.suggested_actions("Cuando estés listo, dime qué quieres analizar.")
    assert actions[1]["message"] == "Haz la segmentación e isofotas de este objeto"
